# Dossier Drive LONGUEUIL_HISTOIRE (15 fichiers), dépouillé le 21 nov. 2026. Préfixe LGU.
# Fiches du réseau : gens de Longueuil liés aux Pays d'en haut, au Détroit, à Michillimakinac et à l'Oregon.
# Les faits propres à la famille Le Moyne sont proposés à l'Atlas Iberville dans longueuil.md, pas ici.
# Pages : pagination imprimée quand elle existe ; sinon « p. N du PDF ».
from commun import Corpus

LEM = "Lemoine, Louis, Longueuil en Nouvelle-France, Longueuil, Société d'histoire de Longueuil, 1975 (PDF, Drive de l'auteur, dossier LONGUEUIL_HISTOIRE)"
FAL = "Falardeau, Émile, Les pionniers de Longueuil et leurs origines, 1666-1681, Montréal, 1937 (PDF, Drive de l'auteur, dossier LONGUEUIL_HISTOIRE)"
JOD = "Jodoin, Alex., et J.-L. Vincent, Histoire de Longueuil et de la famille de Longueuil, Montréal, Granger frères, 1889 (PDF, Drive de l'auteur, dossier LONGUEUIL_HISTOIRE, fichier Histoire_Longueuil.pdf)"
GAU = "Gauthier, Robert, La paroisse de Saint-Antoine de Longueuil, son histoire, ses pasteurs, sa cocathédrale (1698-1998), Longueuil, Éditions du Marigot, [1998] (PDF, Drive de l'auteur, dossier LONGUEUIL_HISTOIRE)"
DOU = "Doucet, Édouard, Longueuil, 1657-2000. 343 ans d'histoire à travers photos, cartes postales et illustrations, 2e éd., Longueuil, Société d'histoire de Longueuil, 1999 (PDF, Drive de l'auteur, dossier LONGUEUIL_HISTOIRE)"

C = Corpus('Recherches', 'LGU', LEM); F = C.F

F('01', "Longueuil : la seigneurie, réservoir d'engagés pour le Détroit et Michillimakinac (1723-1760)", 'commerce', '1723/1760', -73.518, 45.537, 'a',
  ['Louis Lemoine', 'Danré de Blanzy'],
  "Dans les greffes des notaires du gouvernement de Montréal, Louis Lemoine relève 309 contrats d'engagement passés par des habitants de la seigneurie de Longueuil, dont 288 concernent le commerce des fourrures. L'engagement se signe surtout au printemps (247 contrats) et, pour plus de 88 % des pièces, pendant la troisième génération d'habitants, entre 1730 et 1760 ; trois notaires, dont Danré de Blanzy, spécialiste de ces contrats, en rédigent les deux tiers. Sur les cent vingt contrats qui indiquent la destination, cinquante-neuf visent le Détroit et trente-neuf Michillimakinac ; sur les soixante-neuf qui donnent le salaire, la plupart vont de 100 à 399 livres. Quarante-neuf congés et permis de traite, de 1723 à 1752, avec des pointes en 1743, 1745, 1746 et 1749, livrent en outre soixante-douze noms d'habitants de Longueuil engagés à des marchands équipeurs. Lemoine décrit le voyageur comme une catégorie sociale de la seigneurie : le père, plus souvent un fils, part pour les Pays d'en haut, tandis que des fils ou des frères restent aux travaux de la terre. Les censitaires négocient ces engagements à Montréal, où ils passent la plupart de leurs actes.",
  '40-41, 54-55, 110, 115', "Point au vieux Longueuil (site du fort, comme L47 de l'Atlas Iberville). Lemoine ne publie pas la liste nominative des engagés ni des 72 noms des permis ; il renvoie au répertoire de Massicotte (RAPQ 1929-1930) et aux congés publiés dans le RAPQ de 1921-1923. Il note, après Louise Dechêne, que ces départs ne se font pas au détriment de l'agriculture.")

F('02', "Michillimakinac : Louis Edeline, habitant de Longueuil, engagé pour le poste (1727)", 'commerce', '1727-06-14', -84.736, 45.787, 'a',
  ['Louis Edeline', 'Clignancourt', 'Maugras', 'Joseph-Charles Raimbault'],
  "Le 14 juin 1727, devant le notaire Joseph-Charles Raimbault, à Montréal, Louis Edeline, habitant de Longueuil, s'engage aux sieurs de Clignancourt et Maugras « pour faire le voyage de cette ville au poste de Missilimakinac ». Son salaire est de 215 livres, payable au retour en castors au prix du bureau et en pelleteries au prix des marchands équipeurs. Louis Lemoine cite ce contrat comme exemple type des engagements pour l'Ouest passés par les habitants de la seigneurie. C'est l'un des trente-neuf contrats de Longueuil à destination de Michillimakinac qu'il a repérés.",
  '40', "Greffe J.-C. Raimbault, 14 juin 1727 (numéro de minute lu « 93g » dans l'OCR, à vérifier). Point au poste de Michillimakinac (rive sud du détroit), destination du voyage ; le contrat est passé à Montréal. Ne pas confondre avec le Louis Edeline de Vincennes (JO-edeline-louis-vincennes, 1783), dont le lien avec celui-ci n'est pas établi.")

F('03', "Détroit : Barbe Loisel, veuve de deux colons de la région de Longueuil, épouse François Fafard (1713)", 'famille', '1713-10-30', -83.0465, 42.3293, 'a',
  ['Barbe Loisel', 'Pierre Rouxel', 'François Le Gantier de la Vallée-Ranée', 'François Fafard', 'Catherine Primot'],
  "Fille du serrurier Louis Loisel et de Marguerite Chariot (graphie de l'OCR), Barbe Loisel est baptisée le 30 août 1663. Le 26 octobre 1676, elle épouse Pierre Rouxel, maître-taillandier, originaire d'Ouville-la-Rivière près de Dieppe, compté parmi les pionniers de Longueuil ; le mariage est célébré en présence de Catherine Primot, épouse de Charles Le Moyne. Veuve en 1687, elle se remarie le 28 novembre 1689 avec François Le Gantier, sieur de la Vallée-Ranée, officier commandant le fort de Lachine. Le 30 octobre 1713, au Détroit, elle épouse en troisièmes noces François Fafard, veuf de Madeleine Jobin.",
  '79, 87', "Complète HM-loisel-barbe-fort-pontc et HM-fafard-dit-delorme-francois-fort-pontc-2 (Hamlin), qui font déjà de Barbe Loisel l'épouse de Fafard « vers 1710 » ; Falardeau date le mariage du Détroit du 30 octobre 1713 d'après Tanguay (sa source IV). Les deux dates ne s'accordent pas ; celle de Falardeau repose sur un acte. Falardeau, entrées 137 et 167. Point au fort Pontchartrain, comme les fiches existantes.", source=FAL)

F('04', "Détroit : René Deniau, fils d'un pionnier de Longueuil, y est inhumé (1730)", 'personnage', '1730-07-13', -83.0465, 42.3293, 'a',
  ['René Deniau', 'Jean Deniau', 'Hélène Daudin', 'Madeleine Matou'],
  "René Deniau est le fils de Jean Deniau, scieur de long nantais arrivé à Ville-Marie en 1653 avec la grande recrue de Maisonneuve, compté parmi les pionniers de Longueuil et tué par les Iroquois en 1695, et d'Hélène Daudin. Baptisé le 18 janvier 1665, il épouse à Boucherville, le 29 octobre 1692, Madeleine Matou, veuve de Jean Haudecoeur, de Boucherville. Il est inhumé au Détroit le 13 juillet 1730. Falardeau ne dit rien de sa vie dans l'Ouest au-delà de cette sépulture.",
  '99-100', "Falardeau, entrées 208 et 213 ; dates tirées des registres de Montréal et de Boucherville et de Tanguay (sources I, II et IV de Falardeau). Le reseau n'a pour ce nom que le récollet Chérubin Deniau (CP-deniau-cherubin-fort-pontc), sans lien établi. Point au fort Pontchartrain du Détroit.", source=FAL)

F('05', "Longueuil : le récollet Constantin Delhalle, futur aumônier du Détroit, y exerce en 1698", 'religion', '1698', -73.518, 45.537, 'a',
  ['Constantin Delhalle', 'Pierre Millet', 'Cyprien Tanguay'],
  "Arrivé de France le 1er juin 1696, le récollet Nicolas-Bernardin-Constantin de L'Halle (Constantin Delhalle) signe quelques actes à Longueuil en 1698, comme missionnaire, l'année où le jésuite Pierre Millet devient le premier curé à résidence de la paroisse Saint-Antoine. Jodoin et Vincent citent le Répertoire du clergé de Tanguay : il dessert ensuite la paroisse de Saint-François de Sales, devient en 1703 le premier aumônier du fort Pontchartrain du Détroit et y est tué par les Outaouais le 1er juin 1706. Ils citent aussi, d'après Tanguay, une note des registres du Détroit datée du 4 au 13 mai 1723 : son corps est exhumé et transporté dans la nouvelle église. Jodoin et Vincent contestent sa mort de 1706, parce qu'un « père Bernardin-Constantin » est curé de Longueuil de 1713 à 1715 ; Gauthier explique cette confusion par l'existence de deux récollets : Nicolas Bernardin, dit père Constantin, curé de 1713 à 1715, et Constantin de Halle, venu en 1698.",
  'Jodoin et Vincent, p. 194-195 ; Gauthier, p. 36', "Le séjour au Détroit et la mort de 1706 sont déjà dans CP-delhalle-constantin-fort-pontc, RC-delhalle-constantin-fort-pontc et RH-delhalle-constantin-fort-pontc (qui datent l'attaque du 2 juin 1706 ; Tanguay, cité par Jodoin, dit le 1er juin). Apport : son passage à Longueuil en 1698 et l'exhumation de 1723. Point au vieux Longueuil, où le fort servait alors d'église.",
  source="Jodoin, Alex., et J.-L. Vincent, Histoire de Longueuil et de la famille de Longueuil, Montréal, Granger frères, 1889 ; Gauthier, Robert, La paroisse de Saint-Antoine de Longueuil (1698-1998), Longueuil, Éditions du Marigot, [1998] (PDF, Drive de l'auteur, dossier LONGUEUIL_HISTOIRE)")

F('06', "Longueuil : trois Sœurs des Saints Noms de Jésus et de Marie partent rejoindre la mission d'Oregon (1864)", 'religion', '1864-02-02', -73.5165, 45.5375, 'a',
  ['Martine Tessier', 'Françoise Dubreuil', 'Adeline Chouinard', 'Edwige Davignon'],
  "Le 2 février 1864, trois religieuses quittent le couvent de Longueuil, maison des Sœurs des Saints Noms de Jésus et de Marie, pour rejoindre en Oregon leurs douze consœurs du contingent précédent. Ce sont Martine Tessier, Françoise Dubreuil et Adeline Chouinard ; elles sont accompagnées par Edwige Davignon. Selon la même chronologie, la congrégation avait été fondée à Longueuil le 28 octobre 1843.",
  "p. 14 et 23 du PDF (éphémérides de 1843 et de 1864)", "Doucet donne les noms civils, sans noms de religion. Le contingent de 1859 arrivé à Portland est déjà dans le reseau (BB-renauld-adelaide-portland, BB-lachappelle-martine-portland, etc.) ; ce renfort de 1864 n'y figure pas. La fondation de 1843 est dans la même chronologie de Doucet. Point approximatif au couvent de la rue Saint-Charles, dans le vieux Longueuil.", source=DOU)

fiches = C.fiches
